<?php
declare(strict_types=1);
use Vendi\Database\Connection;
require dirname(__DIR__).'/vendor/autoload.php';
$db=Connection::make(['host'=>getenv('DB_HOST')?:'127.0.0.1','port'=>(int)(getenv('DB_PORT')?:3306),'database'=>getenv('DB_DATABASE')?:'vendi','username'=>getenv('DB_USERNAME')?:'root','password'=>getenv('DB_PASSWORD')?:'']);
$token=preg_replace('/[^a-f0-9]/i','',(string)($_GET['t']??''));if(strlen($token)!==48){http_response_code(404);exit('Ticket no encontrado');}
$q=$db->prepare("SELECT s.id,s.subtotal,s.discount,s.tax,s.total,s.completed_at,s.status,b.name branch_name,b.phone,b.email FROM sales s JOIN branches b ON b.id=s.branch_id WHERE s.public_token=? LIMIT 1");$q->execute([$token]);$s=$q->fetch();if(!$s){http_response_code(404);exit('Ticket no encontrado');}
$i=$db->prepare("SELECT description,qty,unit_price,line_total FROM sale_items WHERE sale_id=?");$i->execute([$s['id']]);$items=$i->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ticket digital | Vendi</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f7fb;color:#172033;font-family:system-ui,-apple-system,sans-serif}.wrap{max-width:680px;margin:auto;padding:22px}.head{text-align:center;margin:10px 0 20px}.head b{font-size:27px}.card{background:#fff;border:1px solid #e4e8ef;border-radius:18px;padding:22px}.meta{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;color:#667085}.item{display:flex;justify-content:space-between;gap:15px;padding:12px 0;border-bottom:1px solid #eee}.item small{display:block;color:#667085;margin-top:3px}.sum{margin-top:15px}.row{display:flex;justify-content:space-between;padding:4px 0}.total{font-size:23px;font-weight:800;margin-top:7px}.actions{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:18px}.btn{border:0;border-radius:12px;padding:14px;text-align:center;text-decoration:none;font-weight:700;cursor:pointer;background:#172033;color:#fff}.btn.primary{background:#176b47}.note{text-align:center;color:#667085;font-size:13px;margin-top:16px}@media(max-width:480px){.wrap{padding:12px}.card{padding:16px}.actions{grid-template-columns:1fr}}</style></head><body><main class="wrap"><header class="head"><b>Vendi</b><div>Tu ticket digital</div></header><section class="card"><div class="meta"><span>Ticket #<?=htmlspecialchars((string)$s['id'])?></span><span><?=htmlspecialchars((string)$s['completed_at'])?></span></div><h2><?=htmlspecialchars($s['branch_name'])?></h2><?php foreach($items as$x):?><div class="item"><div><?=htmlspecialchars($x['description'])?><small><?=rtrim(rtrim(number_format((float)$x['qty'],3,'.',''),'0'),'.')?> × $<?=number_format((float)$x['unit_price'],2)?></small></div><b>$<?=number_format((float)$x['line_total'],2)?></b></div><?php endforeach;?><div class="sum"><div class="row"><span>Subtotal</span><span>$<?=number_format((float)$s['subtotal'],2)?></span></div><?php if((float)$s['discount']>0):?><div class="row"><span>Descuento</span><span>-$<?=number_format((float)$s['discount'],2)?></span></div><?php endif;?><div class="row"><span>IVA</span><span>$<?=number_format((float)$s['tax'],2)?></span></div><div class="row total"><span>Total</span><span>$<?=number_format((float)$s['total'],2)?></span></div></div><div class="actions"><a class="btn" href="ticket-pdf.php?t=<?=urlencode($token)?>">Descargar PDF</a><a class="btn primary" href="facturar.php?t=<?=urlencode($token)?>">Facturar compra</a></div></section><p class="note">Enlace privado de consulta. No compartas este ticket si contiene información que prefieras mantener privada.</p></main></body></html>